/** The events of one clip, or an empty budget if it was never measured. */
export function clipEvents(clip: string): ClipEvents {
  return CLIP_EVENTS[clip] ?? { clip, duration: 0, handPeak: 0, bodyMean: 0, events: [] };
}

/** Bones that count as a strike when a move is supposed to land with the hands. */
export const HANDS = ['L_Hand', 'R_Hand'];

/**
 * The single hardest stop in a clip — the frame worth building a move around.
 *
 * `only` restricts the search to a set of bones, and it matters more than it looks. box_01's
 * hardest arrest is a TOE at 87.2 H/s², beating its hand at 67.4, so an unrestricted search puts
 * the payoff of a move named for its punch down at the character's foot. A move declares which
 * limb it strikes with and the table answers for that limb.
 */
export function loudestArrest(clip: string, only?: readonly string[]): ClipEvent | null {
  const arrests = clipEvents(clip).events.filter(
    (e) => e.kind === 'arrest' && (!only || only.includes(e.bone)),
  );
  if (!arrests.length) return only ? loudestArrest(clip) : null;
  return arrests.reduce((a, b) => ((b.decel ?? 0) > (a.decel ?? 0) ? b : a));
}

/**
 * `n` well-SPACED peaks: the hardest arrest inside each of n equal windows.
 *
 * Taking the n loudest arrests outright does not work — they cluster. dance_05's five loudest all
 * fall inside three frames of each other at 0.433 and 1.633, so a move built on them fires five
 * times in two bursts and then runs silent for a second and a half. One peak per window forces the
 * beats apart while still landing every one of them on a frame the sweep actually found: for
 * dance_05 that gives 0.200, 0.433, 0.833, 1.233, 1.633 — roughly one every 350 ms.
 *
 * `until` shortens the search range, for a move whose last beat still needs room after it.
 */
export function beats(clip: string, n: number, options: { only?: readonly string[]; until?: number } = {}): ClipEvent[] {
  const table = clipEvents(clip);
  const span = options.until ?? table.duration;
  const arrests = table.events.filter(
    (e) => e.kind === 'arrest' && e.at < span && (!options.only || options.only.includes(e.bone)),
  );
  const out: ClipEvent[] = [];
  for (let i = 0; i < n; i += 1) {
    const from = (span * i) / n;
    const to = (span * (i + 1)) / n;
    const inWindow = arrests.filter((e) => e.at >= from && e.at < to);
    if (!inWindow.length) continue;
    out.push(inWindow.reduce((a, b) => ((b.decel ?? 0) > (a.decel ?? 0) ? b : a)));
  }
  return out;
}
